        // Sanitize filename to avoid path issues
        const cleanSessionId = sessionId.replace(/[^a-zA-Z0-9-]/g, '');
        const fileExt = audioBlob.type.includes('mp4') ? 'mp4' : 'webm';
        const fileName = `${cleanSessionId}_${Date.now()}.${fileExt}`;

        // 1. Upload to Supabase Storage 'recordings' bucket
        const { data: uploadData, error: uploadError } = await supabase.storage
          .from('recordings')
          .upload(fileName, audioBlob, {
            contentType: audioBlob.type || `audio/${fileExt}`,
            upsert: true
          });

        if (uploadError) {
          // Detailed error logging to see the actual Supabase error (e.g., bucket not found, RLS)
          console.error("Supabase Storage Upload Error Details:", JSON.stringify(uploadError, null, 2));
          throw uploadError;
        }

        // 2. Get the Public URL
        const { data: { publicUrl } } = supabase.storage
          .from('recordings')
          .getPublicUrl(fileName);

        // 3. Update the Session record with the URL
        const { error: dbError } = await supabase
          .from('sessions')
          .update({ audio_url: publicUrl })
          .eq('id', sessionId);

        if (dbError) throw dbError;

        console.log("Audio saved to Supabase:", publicUrl);
        return publicUrl;
      } catch (e: any) {
        console.error('Supabase audio upload sequence failed, falling back to local.', e);
      }
    }

    // Local Fallback (Base64)
    const reader = new FileReader();
    reader.readAsDataURL(audioBlob);
    reader.onloadend = async () => {
      const base64data = reader.result as string;

      const sessions = getLocal<Session[]>(LOCAL_SESSIONS_KEY, []);
      const updatedSessions = sessions.map(s => 
        s.id === sessionId ? { ...s, audioUrl: base64data } : s
      );
      setLocal(LOCAL_SESSIONS_KEY, updatedSessions);
    };
  }
};

