```sql
-- Enable UUID extension for unique IDs
create extension if not exists "uuid-ossp";

-- 1. Create Leads Table
create table public.leads (
  id uuid default uuid_generate_v4() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  name text,
  company text,
  status text,
  last_interaction text,
  sentiment text,
  phone text,
  interested_in text,
  notes text
);

-- 2. Create Sessions Table (Links to Leads)
create table public.sessions (
  id uuid default uuid_generate_v4() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  lead_id uuid references public.leads(id) on delete cascade,
  transcript jsonb default '[]'::jsonb,
  audio_url text
);

-- 3. Create Agent Configs Table
create table public.agent_configs (
  id uuid default uuid_generate_v4() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null,
  config jsonb not null
);

-- 4. Enable Row Level Security (RLS)
alter table public.leads enable row level security;
alter table public.sessions enable row level security;
alter table public.agent_configs enable row level security;

-- 5. Create Database Policies (Allowing Anonymous Access for this Demo)
-- These policies allow the app to Read/Write without a user login system.

-- Leads Policies
create policy "Enable read access for all users" on public.leads for select using (true);
create policy "Enable insert access for all users" on public.leads for insert with check (true);
create policy "Enable update access for all users" on public.leads for update using (true);
create policy "Enable delete access for all users" on public.leads for delete using (true);

-- Sessions Policies
create policy "Enable read access for all users" on public.sessions for select using (true);
create policy "Enable insert access for all users" on public.sessions for insert with check (true);
create policy "Enable update access for all users" on public.sessions for update using (true);

-- Agent Config Policies
create policy "Enable read access for all users" on public.agent_configs for select using (true);
create policy "Enable insert access for all users" on public.agent_configs for insert with check (true);
create policy "Enable update access for all users" on public.agent_configs for update using (true);

-- 6. Storage Permissions (After you create the 'recordings' bucket)

-- Allow public read access to recordings
create policy "Public Read Access"
on storage.objects for select
using ( bucket_id = 'recordings' );

-- Allow public upload access to recordings
create policy "Public Upload Access"
on storage.objects for insert
with check ( bucket_id = 'recordings' );

