    } catch (error) {
      console.error("Save failed", error);
      setIsSaving(false);
      alert("Failed to save configuration. Please try again.");
    }
  };

  const updateConfig = (section: keyof AgentConfig, data: any) => {
    setConfig({ ...config, [section]: data });
